{
  "status": "SUPPORTED",
  "task_summary": "Prepare and serve coffee and soup for two people using available kitchenware and ingredients.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "coffee_cup",
        "entity_kind": "OBJECT",
        "function": "Holds prepared coffee for consumption.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["mug", "cup", "glass"],
        "required_properties": ["holds_liquid", "drinkable_size"]
      },
      {
        "id": "soup_bowl",
        "entity_kind": "OBJECT",
        "function": "Holds prepared soup for consumption.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["bowl", "dish", "deep_plate"],
        "required_properties": ["holds_food", "eatable_size"]
      },
      {
        "id": "coffee_material",
        "entity_kind": "OBJECT",
        "function": "Primary ingredient for making coffee.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["ground_coffee", "coffee_beans", "instant_coffee"],
        "required_properties": ["taste_like_coffee"]
      },
      {
        "id": "water_material",
