        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["tap_water", "bottled_water"],
        "required_properties": ["is_water", "drinkable"]
      },
      {
        "id": "soup_material",
        "entity_kind": "OBJECT",
        "function": "Primary ingredient for serving soup.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["broth", "stew", "liquid_soup"],
        "required_properties": ["is_soup", "hot"]
      },
      {
        "id": "eating_utensil",
        "entity_kind": "OBJECT",
        "function": "Tool for eating soup.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["spoon", "fork"],
        "required_properties": ["is_cutlery", "fits_spoon"]
      },
      {
        "id": "stirring_utensil",
        "entity_kind": "OBJECT",
        "function": "Tool for mixing coffee ingredients.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["spoon", "stick", "whisk"],
        "required_properties": ["is_stirring_tool"]
      },
      {
        "id": "table",
        "entity_kind": "FIXED_TARGET",
        "function": "Surface for preparation and serving.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "counter", "desk"],
        "required_properties": ["is_horizontal_surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "prep_coffee_mix",
        "relation": "coffee_cup must contain coffee_material and water_material",
        "participant_roles": ["coffee_cup", "coffee_material", "water_material"]
      ,
      "required": true
      },
      {
        "id": "prep_soup_fill",
        "relation": "soup_bowl must contain soup_material",
        "participant_roles": ["soup_bowl", "soup_material"]
      ,
      "required": true
      },
      {
        "id": "serve_pairing",
        "relation": "soup_bowl must be paired with eating_utensil",
        "participant_roles": ["soup_bowl", "eating_utensil"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "mix_coffee",
        "operation": "Combine coffee_material and water_material in coffee_cup",
        "participant_roles": ["coffee_material", "water_material", "coffee_cup"]
      ,
      "operation_count": 2
      },
      {
        "id": "stir_coffee",
        "operation": "Stir contents of coffee_cup with stirring_utensil",
        "participant_roles": ["stirring_utensil", "coffee_cup"]
      ,
      "operation_count": 2
      },
      {
        "id": "fill_soup",
        "operation": "Transfer soup_material into soup_bowl",
        "participant_roles": ["soup_material", "soup_bowl"]
      ,
      "operation_count": 2
      },
      {
        "id": "pair_utensil",
        "operation": "Place eating_utensil next to soup_bowl",
        "participant_roles": ["eating_utensil", "soup_bowl"]
      ,
      "operation_count": 2
      },
      {
        "id": "serve_coffee",
        "operation": "Place prepared coffee_cup on table",
        "participant_roles": ["coffee_cup", "table"]
      ,
      "operation_count": 2
      },
      {
        "id": "serve_soup",
        "operation": "Place prepared soup_bowl on table",
        "participant_roles": ["soup_bowl", "table"]
      ,
      "operation_count": 2
      }
    ]
  },
